events.conditionSnippet:
show: s => s.job > 0 && /ライン生命|研究|医師|医療|技師|バイオ/.test($terraData.J[s.job]?.n || ""),
      w: 0.75,
      cd: 10,
      t: [
        {
          when: s => /ライン生命/.test($terraData.J[s.job]?.n || ""),
          t: "配属先のライン生命のバイオ研究セクションで、感染者の被験者を使い捨てにする非人道的な生体実験の極秘データを目にしてしまった。隠蔽工作が進む中、州の監査局かマスコミへ告発するか迫られた。"
        },
        {
          t: "勤め先のバイオ研究所で、感染者の被験者を使い捨てにする非人道的な生体実験の極秘データを目にしてしまった。隠蔽工作が進む中、州の監査局かマスコミへ告発するか迫られた。"
        }
      ],

show: s => {
      const career = s.lifeRecord?.affiliations?.find(row => row.id === "kazimierz-competition-career");
      return (
        s.age >= 50 &&
        career?.status === "active" &&
        Number.isInteger(career.startedYear) &&
        s.year - career.startedYear >= 10
      );
    },
    once: true,
    w: 0.8,
    t: "競技場の砂塵のなかで剣を振るい続けて、もう十年以上が過ぎた。どれだけ試合を重ねても、傷んだ武具の修理代や次の大会の登録料は自分の懐から出ていく。若い選手たちの速さに息が上がるようになった今、このまま現役を続けるか、裏方の仕事へ退くか考えた。",

show: s => {
      const care = s.lifeRecord?.affiliations?.find(
        x => x.id === "rhodes-care" && ["active", "crisis"].includes(x.status)
      );
      return ![
        "巡回診療の予約あり",
        "巡回受診を延期中",
        "巡回診療を受診済み",
        "巡回診療後、療養を選択",
        "巡回診療後、療養を休止"
      ].includes(care?.role);
    },
    cd: 4,
    w: 0.42,
    t: "ロドスの現地担当者から、今後の関わり方を尋ねる連絡が届いた。自分の体調や仕事の忙しさと照らし合わせ、これからどう付き合っていくか考えた。",
